import { AxisScale } from '@visx/axis';
import React, { PropsWithChildren } from 'react';

import { AnnotationsRendererContext } from '../contexts/AnnotationsRendererContext.js';

export const AnnotationsRendererProvider = ({
  scale,
  showLabels,
  children,
}: PropsWithChildren<{
  scale: AxisScale<number>;
  showLabels?: boolean;
}>) => (
  <AnnotationsRendererContext.Provider value={{ scale, showLabels }}>
    {children}
  </AnnotationsRendererContext.Provider>
);
